style.css:
@-moz-document domain("youtube.com") {
/* 1. Set your custom background image across the whole page */
  body, html, #page-manager, ytd-app, #content {
    background: url('https://storage.exmeaning.com/sekai-tw-assets/character/member/res001_no025/card_normal.webp') no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* 2. Remove video card backgrounds completely so your wallpaper shows through */
  ytd-rich-item-renderer, 
  ytd-video-renderer, 
  ytd-compact-video-renderer,
  ytd-grid-video-renderer {
    background-color: transparent !important;
    background: transparent !important;
    box-shadow: none !important;
  }
}
